// One line per slot: its $state, so the two reads can be compared at a glance.
return $input.all().map((item) => {
	const metadata = item.json.$metadata ?? {};
	const slots = {};
	for (const [name, entry] of Object.entries(metadata)) {
		if (!name.startsWith('$')) slots[name] = entry?.$state;
	}
	return {
		json: {
			slots,
			checkpoint: typeof metadata.$resume === 'string' ? 'present (more to resume)' : 'none (nothing left open)',
			changedAt: metadata.$changedAt ?? null,
		},
	};
});

